// Authentic Calibri font binary data for Cloudflare Workers PDF generation
function base64ToUint8Array(base64) {
  if (typeof Buffer !== "undefined") {
    return new Uint8Array(Buffer.from(base64, "base64"));
  }
  const binaryString = atob(base64);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

export const CALIBRI_REGULAR_BASE64 = "";
export const CALIBRI_BOLD_BASE64 = "";
export const CALIBRI_ITALIC_BASE64 = "";

let cachedRegularBytes = null;
let cachedBoldBytes = null;
let cachedItalicBytes = null;

export function getCalibriRegularBytes() {
  if (!cachedRegularBytes) {
    cachedRegularBytes = base64ToUint8Array(CALIBRI_REGULAR_BASE64);
  }
  return cachedRegularBytes;
}

export function getCalibriBoldBytes() {
  if (!cachedBoldBytes) {
    cachedBoldBytes = base64ToUint8Array(CALIBRI_BOLD_BASE64);
  }
  return cachedBoldBytes;
}

export function getCalibriItalicBytes() {
  if (!cachedItalicBytes) {
    cachedItalicBytes = base64ToUint8Array(CALIBRI_ITALIC_BASE64);
  }
  return cachedItalicBytes;
}
